let vehicleCustomers=[],vehicleBrands=[],batchVehicles=[],batchBusy=false,vehicleLookupReady=false;
let singleVehicleId=crypto.randomUUID();
const el=id=>document.getElementById(id);
function vehicleMessage(id,text,error=false){el(id).textContent=text;el(id).className='customer-message '+(error?'error':'success')}
async function apiData(path,options){const response=await fetch(path,options);let data;try{data=await response.json()}catch{throw new Error('ไม่สามารถเชื่อมต่อระบบได้ กรุณาลองใหม่')}if(!response.ok){const error=new Error(data.error||'ดำเนินการไม่สำเร็จ');error.rows=data.errors;throw error}return data}
function vehicleOptions(select,rows,label){const selected=select.value;select.innerHTML='<option value="">'+label+'</option>'+rows.map(r=>'<option value="'+esc(r.id)+'">'+esc(r.name)+'</option>').join('');select.value=selected}
async function loadVehicleLookups(){vehicleLookupReady=false;el('vehicle-save').disabled=true;el('batch-file').disabled=true;vehicleMessage('vehicle-lookup-message','กำลังโหลดลูกค้าและยี่ห้อ…');try{const [c,b]=await Promise.all([apiData('/api/customers'),apiData('/api/brands')]);vehicleCustomers=c.customers;vehicleBrands=b.brands;vehicleOptions(el('vehicle-customer'),vehicleCustomers.map(c=>({...c,name:[c.name,c.company,c.branch].filter(Boolean).join(' · ')})),'เลือกลูกค้า');vehicleOptions(el('vehicle-brand'),vehicleBrands,'เลือกยี่ห้อ');vehicleLookupReady=true;el('vehicle-save').disabled=false;el('batch-file').disabled=false;vehicleMessage('vehicle-lookup-message',!vehicleCustomers.length?'ยังไม่มีลูกค้า กรุณาเพิ่มในเมนูฐานข้อมูลลูกค้าก่อน':!vehicleBrands.length?'ยังไม่มียี่ห้อ กดเพิ่มยี่ห้อเพื่อใช้ในรายการรถ':'')}catch(e){vehicleMessage('vehicle-lookup-message',e.message,true)}}
function openVehicleEntry(){el('vehicle-entry').hidden=false;if(!el('vehicle-date').value){const now=new Date();el('vehicle-date').value=[now.getFullYear(),String(now.getMonth()+1).padStart(2,'0'),String(now.getDate()).padStart(2,'0')].join('-')}loadVehicleLookups();loadVehicles()}
function setVehicleTab(name){el('vehicle-single').hidden=name!=='single';el('vehicle-batch').hidden=name!=='batch';document.querySelectorAll('.vehicle-tab').forEach(b=>{const selected=b.dataset.tab===name;b.classList.toggle('selected',selected);b.setAttribute('aria-selected',String(selected))})}
function openBrandForm(){el('brand-inline').hidden=!el('brand-inline').hidden;if(!el('brand-inline').hidden)el('brand-name').focus()}
el('brand-form').addEventListener('submit',async event=>{event.preventDefault();const button=el('brand-add');button.disabled=true;try{const data=await apiData('/api/brands',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:el('brand-name').value})});await loadVehicleLookups();el('vehicle-brand').value=data.brand.id;el('brand-form').reset();el('brand-inline').hidden=true;vehicleMessage('vehicle-lookup-message','เพิ่มยี่ห้อเรียบร้อยแล้ว')}catch(e){vehicleMessage('brand-message',e.message,true)}finally{button.disabled=false}});
async function saveVehicleRows(rows){return apiData('/api/vehicles',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({vehicles:rows})})}
el('vehicle-form').addEventListener('submit',async event=>{event.preventDefault();if(!vehicleLookupReady)return;const form=event.currentTarget;const row=normalizeVehicle(Object.fromEntries(new FormData(form)));const errors=vehicleErrors(row);if(errors.length){vehicleMessage('single-message',errors.join(' · '),true);return}el('vehicle-save').disabled=true;vehicleMessage('single-message','กำลังบันทึก…');try{await saveVehicleRows([{...row,id:singleVehicleId}]);singleVehicleId=crypto.randomUUID();form.reset();vehicleMessage('single-message','บันทึกข้อมูลรถเรียบร้อยแล้ว');await loadVehicles()}catch(e){vehicleMessage('single-message',e.message,true)}finally{el('vehicle-save').disabled=false}});
async function loadVehicles(){const box=el('vehicle-list');box.innerHTML='<div class="empty-customers">กำลังโหลดรายการรถ…</div>';try{const data=await apiData('/api/vehicles');window.savedVehicles=data.vehicles;box.innerHTML=!data.vehicles.length?'<div class="empty-customers">ยังไม่มีข้อมูลรถจดใหม่</div>':'<div class="table-wrap"><table><thead><tr><th>วันที่</th><th>ชื่อลูกค้า</th><th>เลขตัวถัง</th><th>ยี่ห้อ</th><th>จังหวัดที่จดทะเบียน</th><th></th></tr></thead><tbody>'+data.vehicles.map((v,i)=>'<tr><td>'+esc(v.date)+'</td><td>'+esc(v.customerName)+'</td><td>'+esc(v.chassis)+'</td><td>'+esc(v.brandName)+'</td><td>'+esc(v.registration_province||'—')+'</td><td><button class="text-button" onclick="vehicleDetails('+i+')">ดูข้อมูล</button></td></tr>').join('')+'</tbody></table></div>'}catch(e){box.innerHTML='<div class="empty-customers" role="alert">'+esc(e.message)+'</div>'}}
function vehicleDetails(i){const v=window.savedVehicles[i],map={customerId:'customerName',brandId:'brandName',registrationProvince:'registration_province',ownerProvince:'owner_province'};el('dialog-body').innerHTML='<h2>ข้อมูลรถจดใหม่</h2><dl class="customer-detail">'+vehicleColumns.map(([k,label])=>'<div><dt>'+label+'</dt><dd>'+esc(v[map[k]||k]||'—')+'</dd></div>').join('')+'</dl>';el('dialog').showModal()}
function downloadVehicleCSV(){const line=vehicleColumns.map(([,label])=>label).join(',')+'\r\n';downloadBlob(new Blob(['\ufeff'+line],{type:'text/csv;charset=utf-8'}),'vehicle-import-template.csv')}
function downloadBlob(blob,name){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
let batchSourceRows=[];
let excelPromise;
function loadExcel(){if(window.ExcelJS)return Promise.resolve(window.ExcelJS);if(!excelPromise)excelPromise=new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='/assets/exceljs.min.js';script.onload=()=>resolve(window.ExcelJS);script.onerror=()=>{excelPromise=null;script.remove();reject(new Error('โหลดตัวอ่าน Excel ไม่สำเร็จ กรุณาลองใหม่'))};document.head.appendChild(script)});return excelPromise}
function parseCSV(text){const rows=[];let row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++}else if(!quoted&&cell!=='')throw new Error('รูปแบบ CSV ไม่ถูกต้อง');else quoted=!quoted}else if(c===','&&!quoted){row.push(cell);cell=''}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);rows.push(row);row=[];cell=''}else cell+=c}if(quoted)throw new Error('เครื่องหมายคำพูดใน CSV ไม่ครบ');if(row.length||cell){row.push(cell);rows.push(row)}return rows}
function lookupId(value,rows,label){const exact=rows.filter(r=>r.id===value);if(exact.length===1)return exact[0].id;const matches=rows.filter(r=>r.name===value);if(matches.length===1)return matches[0].id;throw new Error(matches.length?'ชื่อ'+label+'ซ้ำ กรุณาใช้รหัสจากรายการอ้างอิง':'ไม่พบ'+label+'ในฐานข้อมูล')}
function downloadLookupCSV(){const quote=v=>'"'+String(v).replaceAll('"','""')+'"';const rows=[['ประเภท','รหัส','ชื่อ','บริษัท','สาขา'],...vehicleCustomers.map(c=>['ลูกค้า',c.id,c.name,c.company,c.branch]),...vehicleBrands.map(b=>['ยี่ห้อ',b.id,b.name,'',''])];downloadBlob(new Blob(['\ufeff'+rows.map(r=>r.map(quote).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}),'vehicle-reference.csv')}
el('batch-file').addEventListener('change',async event=>{if(batchBusy)return;batchVehicles=[];el('batch-save').disabled=true;el('batch-preview').innerHTML='';const file=event.target.files[0];if(!file)return;batchBusy=true;event.target.disabled=true;vehicleMessage('batch-message','กำลังตรวจไฟล์…');try{if(file.size>5*1024*1024)throw new Error('ไฟล์ต้องไม่เกิน 5 MB');let rows;if(/\.csv$/i.test(file.name)){rows=parseCSV(new TextDecoder('utf-8',{fatal:true}).decode(await file.arrayBuffer()).replace(/^\uFEFF/,''))}else if(/\.xlsx$/i.test(file.name)){const Excel=await loadExcel();const book=new Excel.Workbook();await book.xlsx.load(await file.arrayBuffer());const sheet=book.worksheets[0];if(!sheet)throw new Error('ไม่พบชีตข้อมูล');if(sheet.rowCount>101)throw new Error('รองรับไม่เกิน 100 แถวต่อไฟล์');rows=[];sheet.eachRow({includeEmpty:true},r=>{const values=[];for(let i=1;i<=Math.max(12,r.cellCount);i++){const cell=r.getCell(i),v=cell.value;if(v&&typeof v==='object'&&('formula'in v||'sharedFormula'in v))throw new Error('ไม่รองรับสูตร Excel กรุณาวางเป็นค่า');values.push(v instanceof Date?v.toISOString().slice(0,10):cell.text)}rows.push(values)})}else throw new Error('เลือกไฟล์ .xlsx หรือ .csv เท่านั้น');rows.forEach((r,i)=>r.sourceRow=i+1);rows=rows.filter(r=>r.some(c=>String(c).trim()));if(rows.length<2)throw new Error('ไฟล์ยังไม่มีข้อมูลรถ');if(rows.length>101)throw new Error('รองรับไม่เกิน 100 แถวต่อไฟล์');const header=rows.shift().map(c=>String(c).trim()==='ลักษณะรถ'?'ประเภทรถ':String(c).trim());const indexes=vehicleColumns.map(([key,label])=>{const index=header.findIndex(x=>x===label||x===key);if(index<0)throw new Error('ไม่พบคอลัมน์ '+label);if(header.filter(x=>x===label||x===key).length>1)throw new Error('คอลัมน์ซ้ำ: '+label);return index});const seen=new Set();let bad=0;batchSourceRows=rows.map(r=>r.sourceRow);const previews=rows.map((raw,index)=>{const values=normalizeVehicle(Object.fromEntries(vehicleColumns.map(([k],i)=>[k,raw[indexes[i]]??''])));const issues=[];try{values.customerId=lookupId(values.customerId,vehicleCustomers,'ลูกค้า')}catch(e){issues.push(e.message)}try{values.brandId=lookupId(values.brandId,vehicleBrands,'ยี่ห้อ')}catch(e){issues.push(e.message)}issues.push(...vehicleErrors(values));if(seen.has(values.chassis))issues.push('เลขตัวถังซ้ำในไฟล์');seen.add(values.chassis);if(issues.length)bad++;batchVehicles.push({...values,id:crypto.randomUUID()});return '<tr><td>'+raw.sourceRow+'</td><td>'+esc(raw[indexes[1]])+'</td><td>'+esc(values.chassis)+'</td><td class="'+(issues.length?'import-error':'import-ok')+'">'+esc(issues.length?issues.join(' · '):'พร้อมนำเข้า')+'</td></tr>'});el('batch-preview').innerHTML='<div class="table-wrap"><table><thead><tr><th>แถว</th><th>ลูกค้า</th><th>เลขตัวถัง</th><th>ผลตรวจสอบ</th></tr></thead><tbody>'+previews.join('')+'</tbody></table></div>';el('batch-save').disabled=bad>0;vehicleMessage('batch-message','พบ '+rows.length+' รายการ'+(bad?' · ต้องแก้ไข '+bad+' แถว แล้วเลือกไฟล์ใหม่':' · ตรวจสอบแล้ว กดบันทึกเพื่อนำเข้า'),bad>0)}catch(e){batchVehicles=[];vehicleMessage('batch-message',e.message,true)}finally{batchBusy=false;event.target.disabled=!vehicleLookupReady}});
async function saveBatchVehicles(){if(batchBusy||!batchVehicles.length)return;batchBusy=true;el('batch-save').disabled=true;el('batch-file').disabled=true;vehicleMessage('batch-message','กำลังบันทึก…');try{const result=await saveVehicleRows(batchVehicles);vehicleMessage('batch-message','บันทึกแล้ว '+result.count+' รายการ');batchVehicles=[];el('batch-file').value='';el('batch-preview').innerHTML='';await loadVehicles()}catch(e){vehicleMessage('batch-message',e.message+(e.rows?' · '+e.rows.map(r=>'แถว '+(batchSourceRows[r.row-1]||r.row+1)+': '+r.errors.join(', ')).join(' / '):''),true);el('batch-save').disabled=false}finally{batchBusy=false;el('batch-file').disabled=!vehicleLookupReady}}

document.getElementById('vehicle-type').innerHTML='<option value="">เลือกประเภทรถ</option>'+vehicleTypes.map(t=>'<option value="'+esc(t)+'">'+esc(t)+'</option>').join('');
